<script setup lang="ts">
import TeacherToday from './TeacherToday.vue'
import {homeworkMatches} from '../teacher-workflow'
import HomeworkRegister from './HomeworkRegister.vue'
import HomeworkProgress from './HomeworkProgress.vue'
import EnglishDateInput from './EnglishDateInput.vue'
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import MonthlyAttendance from './MonthlyAttendance.vue'
import DailyMenu from './DailyMenu.vue'
import ClassNotices from './ClassNotices.vue'
import {scheduleApi,days} from '../schedules'
defineProps<{loginId:string;busy:boolean;error:string}>()
const emit=defineEmits<{logout:[]}>()
const data=ref<any>(null),page=ref('today'),loading=ref(false),saving=ref(false),error=ref(''),message=ref('')
const classId=ref(0),day=ref(7),students=ref<any[]>([]),homework=ref<any[]>([])
const progressDialog=ref<HTMLDialogElement>(),trackedHomework=ref<any>(null),progressBusy=ref(false),progressDirty=ref(false),registerRevision=ref(0)
async function openProgress(h:any){trackedHomework.value=h;await nextTick();progressDialog.value?.showModal()}
function closeProgress(){if(progressBusy.value)return;if(progressDirty.value&&!window.confirm('Discard unsaved homework statuses?'))return;progressDialog.value?.close();registerRevision.value++;trackedHomework.value=null;progressDirty.value=false}
const form=reactive({id:0,version:0,assignment:'',title:'',instructions:'',due_on:'',is_active:true})
const classes=computed<any[]>(()=>[...new Map<number,any>([...(data.value?.assignments??[]),...(data.value?.homerooms??[])].map(c=>[c.class_id,c])).values()])
const currentLessons=computed(()=>(data.value?.lessons??[]).filter((l:any)=>l.day_of_week===day.value))
const label=(c:any)=>'Grade '+c.grade_label+' · Class '+c.class_name
function assignment(id:number){return data.value?.assignments.find((a:any)=>a.offering_id===id)}
const rosterSearch=ref(''),rosterPage=ref(1)
const filteredStudents=computed(()=>students.value.filter(s=>(s.full_name+' '+s.login_id).toLowerCase().includes(rosterSearch.value.trim().toLowerCase())))
const rosterPages=computed(()=>Math.max(1,Math.ceil(filteredStudents.value.length/10)))
const visibleStudents=computed(()=>filteredStudents.value.slice((rosterPage.value-1)*10,rosterPage.value*10))
watch([rosterSearch,classId],()=>rosterPage.value=1)
const attendanceBusy=ref(false),noticeBusy=ref(false)
const homeworkClass=ref(0),homeworkSearch=ref(''),homeworkFilter=ref('all')
const formBaseline=ref('')
const formDirty=computed(()=>form.id?JSON.stringify(form)!==formBaseline.value:Boolean(form.title.trim()||form.instructions.trim()))
function discardDraft(){if(!formDirty.value)return true;if(!window.confirm('Discard your unsaved homework draft?'))return false;resetHomework();return true}
function logout(){if(discardDraft())emit('logout')}
function protectDraft(e:BeforeUnloadEvent){if(formDirty.value||progressDirty.value||attendanceBusy.value){e.preventDefault();e.returnValue=''}}
async function todayQuick(mode:string,id:number){if(!discardDraft())return;classId.value=id;await openQuick(mode)}
async function todayRegister(id:number){classId.value=id;await open('register')}
function revealHomework(){void nextTick(()=>document.getElementById('teacher-homework-form')?.scrollIntoView({block:'start',behavior:'smooth'}))}
function reuse(h:any){if(!discardDraft())return;resetHomework();form.assignment=h.class_id+':'+h.offering_id;form.title=h.title;form.instructions=h.instructions;message.value='Copied into a new draft. Choose its due date before assigning.';revealHomework()}
const quickDialog=ref<HTMLDialogElement|null>(null),quickMode=ref(''),quickClassId=ref(0)
const quickClass=computed(()=>classes.value.find(c=>c.class_id===quickClassId.value))
const quickAssignments=computed(()=>data.value?.assignments.filter((a:any)=>a.class_id===quickClassId.value)??[])
async function openQuick(mode:string){if(saving.value||noticeBusy.value||!classId.value)return;quickMode.value=mode;quickClassId.value=classId.value;error.value='';if(mode==='homework'){resetHomework();form.assignment=quickAssignments.value.length===1?quickClassId.value+':'+quickAssignments.value[0].offering_id:''}await nextTick();quickDialog.value?.showModal()}
function closeQuick(){if(saving.value||noticeBusy.value)return;if(quickMode.value==='homework'?!discardDraft():!window.confirm('Close this notice form? Unsaved changes will be discarded.'))return;quickDialog.value?.close();quickMode.value='';resetHomework();error.value=''}
function noticeSaved(){quickDialog.value?.close();quickMode.value='';message.value='Class notice saved.'}
const classHomework=computed(()=>homework.value.filter(h=>(!homeworkClass.value||h.class_id===homeworkClass.value)&&homeworkMatches(h,data.value?.today??'',homeworkSearch.value,homeworkFilter.value)))
let timer:ReturnType<typeof setTimeout>|undefined,readVersion=0
watch(message,v=>{clearTimeout(timer);if(v)timer=setTimeout(()=>message.value='',4000)})
onUnmounted(()=>{clearTimeout(timer);readVersion++;window.removeEventListener('beforeunload',protectDraft)})
function resetHomework(){const options=(data.value?.assignments??[]).filter((a:any)=>a.class_id===classId.value);Object.assign(form,{id:0,version:0,assignment:options.length===1?classId.value+':'+options[0].offering_id:'',title:'',instructions:'',due_on:data.value?.today??'',is_active:true});formBaseline.value=JSON.stringify(form)}
async function load(){
 if(!discardDraft())return;loading.value=true;error.value=''
 const previous=Boolean(data.value)
 try{data.value=await scheduleApi('teacher/dashboard');if(!previous)day.value=new Date(data.value.today+'T00:00:00Z').getUTCDay()||7;if(!classes.value.some(c=>c.class_id===classId.value))classId.value=classes.value[0]?.class_id??0;resetHomework();await loadPage()}
 catch(e){error.value=e instanceof Error?e.message:'Unable to load teacher workspace.'}
 finally{loading.value=false}
}
async function loadPage(){
 const version=++readVersion;error.value='';students.value=[]
 try{
  if(page.value==='students'&&classId.value){const r=await scheduleApi('teacher/classes/'+classId.value+'/students');if(version===readVersion){students.value=r.students;rosterPage.value=1}}
  if(page.value==='homework'||page.value==='register'||page.value==='today'){const r=await scheduleApi('teacher/homework');if(version===readVersion)homework.value=r.homework}
 }catch(e){if(version===readVersion)error.value=e instanceof Error?e.message:'Unable to load this page.'}
}
const studentDialog=ref<HTMLDialogElement|null>(null),studentDetails=ref<any>(null),studentLoading=ref(false),studentError=ref('')
let studentRequest=0
async function openStudent(id:number){const ticket=++studentRequest,selectedClass=classId.value;studentDetails.value=null;studentError.value='';studentLoading.value=true;await nextTick();studentDialog.value?.showModal();try{const r=await scheduleApi('teacher/classes/'+selectedClass+'/students/'+id);if(ticket===studentRequest)studentDetails.value=r.student}catch(e){if(ticket===studentRequest)studentError.value=e instanceof Error?e.message:'Unable to load student.'}finally{if(ticket===studentRequest)studentLoading.value=false}}
function closeStudent(){studentRequest++;studentDialog.value?.close();studentDetails.value=null;studentLoading.value=false}
const lessonClasses=ref<any[]>([]),lessonClassDialog=ref<HTMLDialogElement|null>(null)
async function showClassStudents(id:number){classId.value=id;rosterSearch.value='';lessonClassDialog.value?.close();await open('students')}
async function openLessonClass(offeringId:number){const choices=(data.value?.assignments??[]).filter((a:any)=>a.offering_id===offeringId);if(!choices.length)return;if(choices.length>1){lessonClasses.value=choices;await nextTick();lessonClassDialog.value?.showModal();return}await showClassStudents(choices[0].class_id)}
async function open(next:string){if(next!==page.value&&!discardDraft())return;if(next==='homework'&&classId.value)homeworkClass.value=classId.value;page.value=next;await loadPage()}
async function saveHomework(){
 saving.value=true;error.value=''
 try{
  const [cl,off]=form.assignment.split(':').map(Number)
  const r=await scheduleApi('teacher/homework'+(form.id?'/'+form.id:''),form.id?'PUT':'POST',{class_id:cl,offering_id:off,title:form.title,instructions:form.instructions,due_on:form.due_on,version:form.version,is_active:form.is_active})
  message.value=r.message;if(quickMode.value==='homework'){quickDialog.value?.close();quickMode.value=''}resetHomework();await loadPage()
 }catch(e){error.value=e instanceof Error?e.message:'Unable to save homework.'}finally{saving.value=false}
}
function edit(h:any){if(!discardDraft())return;Object.assign(form,{id:h.id,version:h.version,assignment:h.class_id+':'+h.offering_id,title:h.title,instructions:h.instructions,due_on:h.due_on,is_active:Boolean(h.is_active)});formBaseline.value=JSON.stringify(form);revealHomework()}
onMounted(()=>{window.addEventListener('beforeunload',protectDraft);void load()})
</script>
<template><div class="teacher-shell"><header><a class="brand" href="/">S<span>StudentHub</span></a><button class="secondary" :disabled="busy||saving||attendanceBusy||noticeBusy" @click="logout">Log out</button></header><main>
<div class="welcome"><div><p class="eyebrow">TEACHER WORKSPACE · {{data?.school?.name||'Your school'}}</p><h1>{{data?.teacher?.name||loginId}}</h1><p>{{data?.teacher?.staff_code}} · Your lessons, classes and daily tasks.</p></div><button class="secondary" :disabled="loading||saving||attendanceBusy||noticeBusy" @click="load">Refresh workspace</button></div>
<nav aria-label="Teacher navigation"><button v-for="t in [{id:'today',name:'Today'},{id:'schedule',name:'My schedule'},{id:'students',name:'Class students'},{id:'homework',name:'Homework & notices'},{id:'register',name:'Homework register'},{id:'attendance',name:'Homeroom attendance'},{id:'canteen',name:'Canteen'}]" :key="t.id" :class="{secondary:page!==t.id}" :disabled="saving||loading||attendanceBusy||noticeBusy" :aria-current="page===t.id?'page':undefined" @click="open(t.id)">{{t.name}}</button></nav>
<p v-if="error||$props.error" class="error" role="alert">{{error||$props.error}}</p><p v-if="message" class="success" role="status">{{message}}</p><p v-if="loading" role="status">Loading your workspace…</p>
<template v-if="data&&!loading">
<div class="facts"><span>{{classes.length}} assigned class(es)</span><span>Homeroom: {{data.homerooms.length?data.homerooms.map(label).join(', '):'Not assigned'}}</span><span>Nepal time</span></div>
<TeacherToday v-if="page==='today'" :data="data" :homework="homework" @students="showClassStudents" @quick="todayQuick" @register="todayRegister" @attendance="open('attendance')" @track="openProgress" /><section v-if="page==='schedule'" class="panel"><div class="toolbar"><h2>My teaching schedule</h2><label>Day<select v-model="day"><option v-for="d in [7,1,2,3,4,5,6]" :key="d" :value="d">{{days[d-1]}}</option></select></label></div><p class="muted">Weekly lessons in currently active terms · Tiffin 1–2 PM</p><p v-if="!currentLessons.length">No lessons on this day.</p><article v-for="l in currentLessons" :key="l.id" class="lesson"><time>{{l.start_time}}–{{l.end_time}}</time><div><button type="button" class="lesson-link" :disabled="!assignment(l.course_offering_id)" :aria-label="'View students: '+(assignment(l.course_offering_id)?label(assignment(l.course_offering_id)):'class unavailable')" @click="openLessonClass(l.course_offering_id)">{{assignment(l.course_offering_id)?.course_name}}</button><p>{{assignment(l.course_offering_id)?label(assignment(l.course_offering_id)):''}} · {{l.location||'Room not set'}}</p></div></article></section>
<section v-if="page==='students'" class="panel"><div class="toolbar roster-toolbar"><h2>Class students</h2><div class="class-quick-actions"><button type="button" :disabled="!classId||loading||saving" @click="openQuick('homework')">Assign homework</button><button type="button" class="secondary" :disabled="!classId||loading||saving" @click="openQuick('notice')">Post notice</button></div><label>Class<select v-model="classId" :disabled="saving" @change="loadPage"><option v-for="c in classes" :key="c.class_id" :value="c.class_id">{{label(c)}}</option></select></label></div><p class="muted">Students enrolled today. Contact details are kept private.</p><p v-if="!students.length">No students to show for this class.</p><label>Find a student<input v-model="rosterSearch" type="search" placeholder="Name or student ID"></label><p class="muted">{{filteredStudents.length}} students · Page {{rosterPage}} of {{rosterPages}}</p><ol class="roster"><li v-for="s in visibleStudents" :key="s.id"><button type="button" class="lesson-link" @click="openStudent(s.id)">{{s.full_name}}</button><span>{{s.login_id}}</span></li></ol><div class="pager"><button class="secondary" :disabled="rosterPage===1" @click="rosterPage--">Previous</button><button class="secondary" :disabled="rosterPage===rosterPages" @click="rosterPage++">Next</button></div></section>
<div v-if="page==='homework'" class="teacher-homework-layout"><div class="teacher-homework-main"><ClassNotices class="panel class-board" manage :classes="classes" :today="data.today" @busy="noticeBusy=$event" />
<section id="teacher-homework-form" class="panel"><h2>{{form.id?'Edit homework':'Assign homework'}}</h2><p v-if="formDirty" class="draft-note" role="status">Unsaved homework draft</p><form @submit.prevent="saveHomework"><fieldset :disabled="saving"><div class="fields"><label>Class subject<select v-model="form.assignment" required :disabled="!!form.id"><option value="" disabled>Choose your class and subject</option><option v-for="a in data.assignments" :key="a.class_id+':'+a.offering_id" :value="a.class_id+':'+a.offering_id">{{label(a)}} · {{a.course_name}}</option></select></label><label>Due date<EnglishDateInput v-model="form.due_on" type="date" :min="data.today" required /></label></div><label>Title<input v-model="form.title" required maxlength="150"></label><label>Instructions<textarea v-model="form.instructions" required maxlength="2000" rows="3"></textarea></label><label v-if="form.id" class="check"><input v-model="form.is_active" type="checkbox">Visible to students</label><button :disabled="!data.assignments.length">{{saving?'Saving…':form.id?'Save changes':'Assign homework'}}</button><button v-if="form.id||formDirty" type="button" class="secondary" @click="discardDraft">Discard draft</button></fieldset></form></section></div><aside class="panel assignment-sidebar" aria-labelledby="my-assignments-title"><h2 id="my-assignments-title">My assignments</h2><label>Find homework<input v-model="homeworkSearch" type="search" placeholder="Title or instructions"></label><label>Show<select v-model="homeworkFilter"><option value="all">All assignments</option><option value="today">Due today</option><option value="upcoming">Upcoming</option><option value="past">Past due dates</option><option value="archived">Archived</option></select></label><label>Filter by class<select v-model="homeworkClass"><option :value="0">All my classes</option><option v-for="c in classes" :key="c.class_id" :value="c.class_id">{{label(c)}}</option></select></label><p v-if="!classHomework.length">No assignments match these filters.</p><article v-for="h in classHomework" :key="h.id" class="homework"><div><strong>{{h.title}}</strong><small>{{assignment(h.offering_id)?.course_name||'Previous subject'}} · {{classes.find(c=>c.class_id===h.class_id)?label(classes.find(c=>c.class_id===h.class_id)):'Previous class'}} · Due {{h.due_on}} · {{h.is_active?'Visible':'Archived'}}</small><p class="instructions">{{h.instructions}}</p></div><div class="class-quick-actions"><button type="button" @click="openProgress(h)">Track homework</button><button class="secondary" :disabled="saving" @click="edit(h)">Edit</button><button type="button" class="secondary" @click="reuse(h)">Reuse</button></div></article></aside></div>
<section v-if="page==='register'" class="homework-register-panel"><HomeworkRegister v-if="classId" :key="classId+':'+registerRevision+':'+homework.map(h=>h.id).join(',')" :assignments="homework.filter(h=>h.class_id===classId)" :classes="classes" v-model:class-id="classId" @open="openProgress" @busy="attendanceBusy=$event" /></section><section v-if="page==='canteen'" class="panel"><DailyMenu reader="teacher" /></section>
<MonthlyAttendance v-if="page==='attendance'" :classes="data.homerooms" :today="data.today" :initial-class-id="classId" @busy="attendanceBusy=$event" />
</template><dialog ref="studentDialog" class="teacher-quick-dialog" aria-labelledby="student-details-title" @cancel.prevent="closeStudent"><div class="toolbar"><h2 id="student-details-title">Student details</h2><button type="button" class="secondary" @click="closeStudent">Close</button></div><p v-if="studentLoading" role="status">Loading student…</p><p v-else-if="studentError" class="error" role="alert">{{studentError}}</p><dl v-else-if="studentDetails" class="student-detail-list"><dt>Name</dt><dd>{{studentDetails.full_name}}</dd><dt>Student ID</dt><dd>{{studentDetails.login_id}}</dd><dt>School</dt><dd>{{studentDetails.school}}</dd><dt>Class</dt><dd>{{label(studentDetails)}}</dd><dt>Academic year</dt><dd>{{studentDetails.academic_year}}</dd><dt>Usual room</dt><dd>{{studentDetails.room_number||'Not assigned'}}</dd><dt>Joined class</dt><dd>{{studentDetails.joined_on}}</dd></dl><p class="muted">Current school details only. Contact information and account credentials remain private.</p></dialog><dialog ref="lessonClassDialog" class="teacher-quick-dialog" aria-labelledby="lesson-class-title"><div class="toolbar"><h2 id="lesson-class-title">Choose this lesson’s class</h2><button type="button" class="secondary" @click="lessonClassDialog?.close()">Close</button></div><p>This lesson is shared by more than one class.</p><button v-for="c in lessonClasses" :key="c.class_id" type="button" class="secondary" @click="showClassStudents(c.class_id)">{{label(c)}}</button></dialog><dialog ref="quickDialog" class="teacher-quick-dialog" aria-labelledby="quick-title" @cancel.prevent="closeQuick"><div class="toolbar"><div><h2 id="quick-title">{{quickMode==='homework'?'Assign homework':'Post notice'}}</h2><p v-if="quickClass" class="muted">{{label(quickClass)}}</p></div><button type="button" class="secondary" :disabled="saving||noticeBusy" @click="closeQuick">Close</button></div><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="quickMode==='homework'"><p v-if="!quickAssignments.length" class="muted">No current subject assignment for this class. Ask the administrator to assign a subject before creating homework.</p><form @submit.prevent="saveHomework"><fieldset :disabled="saving"><div class="fields"><label>Class subject<select v-model="form.assignment" required :disabled="!!form.id"><option value="" disabled>Choose your class and subject</option><option v-for="a in quickAssignments" :key="a.class_id+':'+a.offering_id" :value="a.class_id+':'+a.offering_id">{{label(a)}} · {{a.course_name}}</option></select></label><label>Due date<EnglishDateInput v-model="form.due_on" type="date" :min="data.today" required /></label></div><label>Title<input v-model="form.title" required maxlength="150"></label><label>Instructions<textarea v-model="form.instructions" required maxlength="2000" rows="3"></textarea></label><label v-if="form.id" class="check"><input v-model="form.is_active" type="checkbox">Visible to students</label><button :disabled="!quickAssignments.length">{{saving?'Saving…':form.id?'Save changes':'Assign homework'}}</button></fieldset></form></template><ClassNotices v-if="quickMode==='notice'" :key="quickClassId" manage compose-only :classes="classes" :initial-class-id="quickClassId" :today="data?.today" @busy="noticeBusy=$event" @saved="noticeSaved" /></dialog>
<dialog ref="progressDialog" class="teacher-quick-dialog" aria-labelledby="homework-tracking-title" @cancel.prevent="closeProgress"><div class="toolbar"><h2 id="homework-tracking-title">Homework progress</h2><button type="button" class="secondary" :disabled="progressBusy" @click="closeProgress">Close</button></div><h3>{{trackedHomework?.title}}</h3><HomeworkProgress v-if="trackedHomework" :key="trackedHomework.id" :homework-id="trackedHomework.id" @busy="progressBusy=$event" @dirty="progressDirty=$event" /></dialog></main></div></template>
<style scoped>
.student-detail-list{display:grid;grid-template-columns:minmax(90px,1fr) 2fr;gap:12px;font-size:14px}.student-detail-list dt{font-weight:600}.student-detail-list dd{margin:0;overflow-wrap:anywhere}.teacher-shell .lesson-link{background:none;color:#245e49;text-decoration:none;font-size:15px;line-height:1.45;font-weight:600;padding:4px 0;min-height:44px;text-align:left;white-space:normal;overflow-wrap:anywhere}.lesson-link:focus-visible{outline:2px solid #21896f;outline-offset:3px}.class-quick-actions{display:flex;gap:8px;flex-wrap:wrap;margin-left:auto}.teacher-quick-dialog{width:min(680px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;border:1px solid #d9e5dc;border-radius:14px;padding:20px;color:#243e33}.teacher-quick-dialog::backdrop{background:#153c2a70}.class-board{margin-bottom:16px}.teacher-shell{max-width:1120px;margin:auto;padding:0 24px;color:#243e33}.teacher-shell header,.welcome,.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.teacher-shell header{padding:22px 0;border-bottom:1px solid #dae5dc}.teacher-shell main{padding:26px 0}.welcome h1{font-size:30px;margin:8px 0}.welcome p{font-size:13px;color:#63796b}.teacher-shell nav{display:flex;gap:8px;overflow:auto;padding:12px 0}.teacher-shell button{width:auto;padding:10px 14px;margin:0;font-size:13px;min-height:40px}.pager{display:flex;justify-content:space-between;gap:10px;margin-top:12px}.facts{display:flex;gap:10px;flex-wrap:wrap;margin:10px 0 18px;font-size:12px}.facts span{background:#eaf2ec;border-radius:20px;padding:8px 12px}.panel{background:white;border:1px solid #d9e5dc;border-radius:14px;padding:20px;min-width:0}.panel h2{font-size:20px;margin:0 0 12px}.toolbar label{font-size:12px}.teacher-shell input,.teacher-shell select,.teacher-shell textarea{font:inherit;font-size:14px;background:white;color:#243e33;border:1px solid #bacebf;border-radius:8px;padding:10px;width:100%;box-sizing:border-box;margin:5px 0 12px}.toolbar select{min-wid